diff --git a/frontend/tests/unit/seo-base-url.test.ts b/frontend/tests/unit/seo-base-url.test.ts
index e893e48..f55f486 100644
--- a/frontend/tests/unit/seo-base-url.test.ts
+++ b/frontend/tests/unit/seo-base-url.test.ts
@@ -8,10 +8,10 @@ import { SITE, siteUrl } from '@/lib/seo';
  * Symptom: site live at https://teww.org for two weeks, `site:teww.org`
  * on Google returned zero results.
  *
- * Root cause: SITE.baseUrl defaulted to `https://www.thirdeyeworldwide.org`
+ * Root cause: SITE.baseUrl defaulted to `https://www.teww.org`
  * — a hostname we don't own — so every <link rel="canonical">, every
  * <loc> in the sitemap, and the Sitemap: directive in robots.txt told
- * Google "the real version of this page is at thirdeyeworldwide.org",
+ * Google "the real version of this page is at teww.org",
  * a domain that returns nothing. Google never indexed teww.org because
  * it had no canonical URL to attribute the content to.
  *
Shell cwd was reset to /Users/taha

